// Card per Home Assistant di Simonz82: elettrodomestici (lavatrice, asciugatrice, lavastoviglie,
// forno, TV), FritzBox, climatizzatore, server Home Assistant, NAS Synology, Proxmox, UPS, energia casa, raccolta
// differenziata e rete Zigbee. Popup Impostazioni/Statistiche/Grafici presi dai package "Centro Controllo".
// Indipendente da altre card: legge/scrive solo via hass.

// Immagine personalizzata (opzione "image"): sostituisce la foto dentro il disegno della card.
function shcHeroImage(hero, image) {
  if (!image || typeof image !== "string") return hero;
  const src = /^(https?:)?\/\//.test(image) || image.startsWith("/") ? image : "/local/" + image;
  const safe = String(src).replace(/"/g, "&quot;");
  if (/<image href="[^"]*"/.test(hero)) return hero.replace(/<image href="[^"]*"/, '<image href="' + safe + '"');
  // Disegno vettoriale senza foto (elettrodomestici): la tua immagine prende il posto del disegno.
  return hero.replace(/(<svg[^>]*>)[\s\S]*<\/svg>/, '$1<image href="' + safe + '" x="8" y="8" width="224" height="224" preserveAspectRatio="xMidYMid meet" onerror="this.style.display=\'none\'"/></svg>');
}

// Data/ora a 2 formati: completo (default, "31/10/2026, 14:20") oppure corto "31/10 14:20" con
// date_format: short, o auto (corto solo su schermi stretti, <= 480 px). Usato sul fronte delle card.
function shcFmtDateTime(d, mode) {
  const narrow = typeof window !== "undefined" && window.innerWidth <= 480;
  if (mode === "short" || (mode === "auto" && narrow)) {
    return d.toLocaleString(shcLoc(), { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }).replace(",", "");
  }
  return d.toLocaleString(shcLoc(), { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
}

// Esegue uno script / scena / pulsante o un'azione completa {action, target, data}.
function shcCallScriptTarget(hass, t) {
  if (!hass || !t) return;
  if (typeof t === "object") {
    const act = String(t.action || t.service || "");
    const i = act.indexOf(".");
    if (i < 1) return;
    const data = { ...(t.data || {}) };
    if (t.target) Object.assign(data, t.target);
    if (t.entity_id && !data.entity_id) data.entity_id = t.entity_id;
    hass.callService(act.slice(0, i), act.slice(i + 1), data);
    return;
  }
  const dom = String(t).split(".")[0];
  const svc = { script: "turn_on", scene: "turn_on", button: "press", input_button: "press", automation: "trigger", switch: "toggle", input_boolean: "toggle" }[dom];
  if (svc) hass.callService(dom, svc, { entity_id: t });
}

